/// Shadows: only for things that float.
abstract final class CmShadow {
  /// Raised surfaces: popups, side popups, dropdowns (#A0A0A0 at 14%, blur 44).
  static const List<BoxShadow> s100 = [BoxShadow(offset: Offset(12, -12), blurRadius: 44, spreadRadius: 0, color: Color.fromRGBO(160, 160, 160, 0.14))];
}
